import { withBlockchainRPC } from '@yellow-org/sdk';
export function buildClientOptions(config) {
    const opts = [];
    if (config.blockchainRPCs) {
        for (const [chainId, rpcUrl] of Object.entries(config.blockchainRPCs)) {
            opts.push(withBlockchainRPC(BigInt(chainId), rpcUrl));
        }
    }
    return opts;
}
export function blockchainRPCsFromEnv() {
    const raw = process.env.NEXT_PUBLIC_BLOCKCHAIN_RPCS ?? '';
    return raw
        .split(',')
        .filter(Boolean)
        .reduce((acc, pair) => {
        const idx = pair.indexOf(':');
        if (idx === -1)
            return acc;
        const chainId = Number(pair.slice(0, idx).trim());
        const rpcUrl = pair.slice(idx + 1).trim();
        if (Number.isFinite(chainId) && rpcUrl)
            acc[chainId] = rpcUrl;
        return acc;
    }, {});
}
